"""One repeat-safe 10,000 Costume Mileage grant to BumbleBee on the test VM."""
import base64,os,subprocess,sys
from pathlib import Path
SQL_BASE64=''
def main():
    if sys.argv[1:]!=['--apply']:raise RuntimeError('APPLY_REQUIRED')
    if os.geteuid()!=0 or Path('/sys/class/dmi/id/product_uuid').read_text().strip().lower()!='7632fb78-37a0-f645-97c0-dc322c50b002':raise RuntimeError('WRONG_TEST_VM_OR_ROOT_REQUIRED')
    shell='''set +x
export SQLCMDPASSWORD="${MSSQL_SA_PASSWORD:-${SA_PASSWORD:-}}"
[ -n "$SQLCMDPASSWORD" ] || exit 2
tool=/opt/mssql-tools18/bin/sqlcmd
[ -x "$tool" ] || tool=/opt/mssql-tools/bin/sqlcmd
exec "$tool" -S localhost -U sa -N -C -d Server01 -b -l 5 -t 30 -h -1 -W -w 65535 -i /dev/stdin
'''
    p=subprocess.run(['docker','exec','-i','sql_main','sh','-ec',shell],input=base64.b64decode(SQL_BASE64,validate=True),capture_output=True,timeout=45)
    raw=p.stdout+p.stderr
    if raw.startswith((b'\xff\xfe',b'\xfe\xff')):text=raw.decode('utf-16',errors='replace')
    elif b'\0' in raw[:100]:text=raw.decode('utf-16-le',errors='replace')
    else:text=raw.decode('utf-8-sig',errors='replace')
    for line in text.splitlines():
        if line.startswith(('BUMBLEBEE_','Msg ')) or any(x in line for x in ('CLOSE_GAME_FIRST','FAILED','DIFFERS','MISSING','Invalid column','Invalid object','WRONG_DATABASE')):print(line[:500],flush=True)
    if p.returncode or not any(x in text for x in ('BUMBLEBEE_MILEAGE_GRANTED;','BUMBLEBEE_MILEAGE_ALREADY_GRANTED;')):raise RuntimeError('MILEAGE_GRANT_NOT_CONFIRMED; KEEP_OUTPUT')
    print('BUMBLEBEE_MILEAGE_CONFIRMED; NEXT_LOGIN; NO_RESTART',flush=True)
if __name__=='__main__':
    try:main()
    except Exception as e:raise SystemExit('BUMBLEBEE_MILEAGE_STOPPED: '+str(e))
